236: .choice-btn:hover { transform: translateY(-1px); border-color: rgba(126,231,255,0.55); box-shadow: 0 0 16px rgba(126,231,255,0.15); }
237: .choice-btn:disabled { opacity: 0.7; cursor: default; }
238: .choice-btn .choice-tag { display: inline-block; margin-bottom: 8px; font-size: 0.68rem; letter-spacing: 0.12em; text-transform: uppercase; color: var(--accent); }
239: .choice-btn strong { display: block; font-size: 1rem; line-height: 1.4; }
