261: .mission-box p,
262: .outcome-box p { margin: 0; line-height: 1.6; color: var(--muted); }
263: .outcome-box.good { border-color: rgba(142,240,184,0.35); }
264: .outcome-box.warn { border-color: rgba(255,215,112,0.35); }
265: .outcome-box.danger { border-color: rgba(255,127,150,0.35); }
266: .outcome-box.good p { color: var(--good); }
267: .outcome-box.warn p { color: var(--warn); }
268: .outcome-box.danger p { color: var(--danger); }
269: 
270: /* Shipyard */
271: .shop-layout { grid-template-columns: minmax(0, 1.5fr) minmax(190px, 0.7fr); }
272: .shop-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }
273: .shop-item { min-width: 0; padding: 12px; border: 1px solid rgba(142,220,255,0.18); border-radius: 14px; background: rgba(17,28,46,0.72); }
274: .shop-item-head { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
275: .shop-item .choice-tag { color: var(--accent); text-transform: uppercase; letter-spacing: 0.1em; font-size: 0.65rem; }
276: .shop-cost { color: var(--warn); font-size: 0.72rem; white-space: nowrap; }
277: .shop-item h3 { margin: 9px 0 5px; font-family: 'Orbitron', sans-serif; font-size: 0.86rem; }
278: .shop-item p { min-height: 4.5em; color: var(--muted); font-size: 0.8rem; line-height: 1.45; }
279: .shop-item .shop-buy { margin-top: 10px; padding: 10px; text-align: center; }
280: .shop-item .shop-buy strong { font-size: 0.82rem; }
281: 
282: /* D20 encounter */
283: .combat-console { display: flex; flex-direction: column; gap: 12px; margin-top: 6px; }
284: .enemy-card { padding: 14px; border: 1px solid rgba(255,127,150,0.35); border-radius: 14px; background: rgba(62,23,39,0.36); }
285: .enemy-card .eyebrow { display: block; margin-bottom: 8px; color: var(--danger); }
286: .enemy-card strong { display: block; font-family: 'Orbitron', sans-serif; }
287: .enemy-card p { margin-top: 6px; color: var(--muted); font-size: 0.86rem; }
288: .action-list { display: grid; grid-template-columns: 1fr; gap: 8px; }
289: .action-btn { padding: 11px 13px; border: 1px solid rgba(142,220,255,0.2); border-radius: 12px; color: var(--text); background: rgba(20,34,52,0.75); text-align: left; cursor: pointer; }
290: .action-btn strong, .action-btn span { display: block; }
291: .action-btn span { margin-top: 4px; color: var(--muted); font-size: 0.76rem; }
292: .action-btn.selected { border-color: var(--accent); box-shadow: inset 0 0 0 1px rgba(126,231,255,0.3); background: rgba(31,67,86,0.55); }
293: .roll-btn { padding: 14px; border: 1px solid rgba(126,231,255,0.55); border-radius: 12px; color: #07101d; background: linear-gradient(110deg, var(--accent), #a7f3d0); font-weight: 800; cursor: pointer; }
294: .dice-note { color: var(--muted) !important; font-size: 0.78rem !important; text-align: center; }
295: .roll-result { display: flex; align-items: center; gap: 14px; padding: 14px; border: 1px solid; border-radius: 14px; }
296: .roll-result.good { border-color: rgba(142,240,184,0.45); background: rgba(31,76,58,0.28); }
297: .roll-result.danger { border-color: rgba(255,127,150,0.45); background: rgba(76,31,45,0.3); }
298: .die-face { display: grid; place-items: center; flex: 0 0 54px; height: 54px; border-radius: 12px; background: rgba(6,13,24,0.8); font-family: 'Orbitron', sans-serif; font-size: 1.5rem; font-weight: 800; }
299: .roll-result strong { display: block; }
300: .roll-result p { margin-top: 5px; color: var(--muted); font-size: 0.86rem; }
301: 
302: @media (max-width: 880px) {
303:   body { padding: 12px; }
304:   .topbar { padding: 12px 14px; }
305:   .game-shell { grid-template-columns: 1fr; }
306:   .scene-body { grid-template-columns: 1fr; }
307:   .shop-layout { grid-template-columns: 1fr; }
308:   .scene-card { min-height: 540px; }
309: }
310: 
311: @media (max-width: 520px) {
312:   .topbar { align-items: flex-start; flex-direction: column; }
313:   .top-actions { width: 100%; justify-content: flex-start; }
314:   .top-actions .ghost-btn { flex: 1; padding: 0.7rem 0.6rem; font-size: 0.82rem; }
315:   .stat-grid { grid-template-columns: 1fr 1fr; }
316:   .scene-top { align-items: flex-start; flex-direction: column; }
317:   .scene-badge { align-self: flex-start; }
318:   .shop-grid { grid-template-columns: 1fr; }
319:   .shop-item p { min-height: 0; }
320:   .scene-card { min-height: 0; }
321: }

