@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@500;600;700&display=swap');
:root{color-scheme:dark;--ink:#f4efe9;--muted:#a9a09a;--faint:#746c68;--wine:#b96370;--gold:#d8b67a;--panel:#1b191c;--line:rgba(255,255,255,.09);--serif:'Playfair Display',Georgia,serif;--sans:'DM Sans',sans-serif}
*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:#121114;color:var(--ink);font-family:var(--sans)}body{min-height:100vh;background:radial-gradient(ellipse at 74% 0%,#38272b 0,transparent 37%),radial-gradient(ellipse at 4% 72%,#28221d 0,transparent 36%),#121114}button{font:inherit;color:inherit}.ambient{position:fixed;pointer-events:none;filter:blur(75px);opacity:.2;border-radius:50%;z-index:0}.ambient-one{width:240px;height:340px;background:#904b57;right:5%;top:20%}.ambient-two{width:280px;height:220px;background:#9c7948;left:0;bottom:2%}.app-shell{position:relative;z-index:1;max-width:1510px;margin:auto;padding:0 40px}.topbar{height:88px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;gap:20px}.brand{display:flex;align-items:center;gap:13px;color:inherit;text-decoration:none}.brand-mark{font-size:27px;color:var(--gold);text-shadow:0 0 25px #d8b67a66}.brand small{display:block;color:var(--muted);font-size:9px;letter-spacing:.21em;margin-bottom:3px}.brand strong{font:600 19px var(--serif);letter-spacing:.01em}.header-actions{display:flex;align-items:center;gap:8px}.quiet-btn{border:1px solid var(--line);border-radius:8px;background:#ffffff06;padding:9px 13px;color:#c9c1bb;cursor:pointer;font-size:12px;transition:.2s}.quiet-btn:hover{border-color:#b963706e;background:#b9637012;color:#fff}.layout{display:grid;grid-template-columns:255px minmax(0,1fr);gap:30px;padding:27px 0 22px;min-height:calc(100vh - 89px)}.sidebar{display:flex;flex-direction:column;gap:16px}.journey-card,.companions-card,.journal-card{background:linear-gradient(145deg,#211f22,#19171a);border:1px solid var(--line);border-radius:12px;padding:17px}.section-kicker,.section-heading{font-size:9px;letter-spacing:.19em;font-weight:700;color:#c8aaa0}.progress-label{display:flex;justify-content:space-between;margin-top:20px;font-size:12px;color:#e4ddd6}.progress-label span:last-child{color:var(--muted);font-size:11px}.progress-track{height:3px;background:#383338;border-radius:9px;margin:9px 0 12px;overflow:hidden}.progress-track span{display:block;width:5%;height:100%;background:linear-gradient(90deg,#a24d5e,#e0bd85);transition:width .5s}.quest-text{font-size:11px;line-height:1.55;color:var(--muted);margin:0}.section-heading{display:flex;justify-content:space-between;align-items:center;color:#bbb1ac;margin-bottom:12px}.tiny-star{color:var(--gold);font-size:13px}.companion-list{display:flex;flex-direction:column;gap:7px}.companion{display:grid;grid-template-columns:35px 1fr auto;align-items:center;gap:9px;padding:8px;border-radius:9px;background:#ffffff04;border:1px solid transparent;transition:.2s}.companion.active{border-color:#b9637033;background:#b963700b}.companion-avatar{width:34px;height:34px;border-radius:50%;display:grid;place-items:center;font-size:14px;background:linear-gradient(145deg,#70444d,#262126);color:#e7c7ad}.companion-name{font:500 12px var(--serif)}.companion-role{font-size:9px;color:var(--muted);margin-top:3px}.bond{font-size:10px;color:var(--gold)}.journal-card{flex:1;min-height:120px}.journal-count{font-size:10px;color:var(--faint)}#journalList{padding:0 0 0 13px;margin:0;display:flex;flex-direction:column;gap:8px;color:#aaa09a;font-size:10px;line-height:1.45;max-height:210px;overflow:auto}#journalList li::marker{color:var(--wine)}.sidebar-foot{text-align:center;color:#827975;font-size:9px;line-height:1.8;padding:1px 0 4px}.sidebar-foot span{color:#695f5c}.play-area{min-width:0;display:flex;flex-direction:column}.scene-card{min-height:690px;flex:1;border:1px solid #ffffff12;background:#1a181b;border-radius:14px;overflow:hidden;position:relative;box-shadow:0 28px 80px #0005}.scene-art{height:300px;position:relative;overflow:hidden;background:var(--scene-bg,linear-gradient(130deg,#302329,#141519 74%));isolation:isolate}.scene-art:before,.scene-art:after{content:"";position:absolute;inset:0;pointer-events:none}.scene-art:before{z-index:-1;background:radial-gradient(ellipse at 72% 